\begin{ex}%[6H4N2]
\immini[thm]{
Nêu tên đỉnh, cạnh, đường chéo, đáy lớn đáy nhỏ của hình thang cân ${MNPQ}$
}{
\begin{tikzpicture}
    % Tọa độ các đỉnh của hình thang cân ABCD
    \coordinate (A) at (0,0);   % Đỉnh A
    \coordinate (B) at (6,0);   % Đỉnh B
    \coordinate (D) at (2,3);   % Đỉnh D
    \coordinate (C) at (4,3);   % Đỉnh C

    % Vẽ hình thang cân ABCD
    \draw[thick] (A) -- (B) -- (C) -- (D) -- cycle;

    % Ghi nhãn các đỉnh
    \node[below left] at (A) {$M$};
    \node[below right] at (B) {$N$};
    \node[above right] at (C) {$P$};
    \node[above left] at (D) {$Q$};
\end{tikzpicture}
}
\loigiai{
Xét hình thang cân $MNPQ$ quan sát trên hình vẽ:\\
- $4$ đỉnh là: $M, N, P, Q$.\\
- $4$ cạnh là: $MN, NP, PQ, QM$ (hai cạnh đáy song song là $MN$ và $PQ$, hai cạnh bên bằng nhau là $NP = QM$).\\
- $2$ đường chéo bằng nhau là: $MP$ và $NQ$.
}\end{ex}

